import argparse
import os
import sys
from typing import Any, Dict, List, Optional

__CEREBRAS_DOC_NOTES__ = "GLM 4.7 Cerebras model id is zai-glm-4.7 and max_completion_tokens is up to 40k. [page:1] clear_thinking defaults to true; setting clear_thinking to false preserves thinking across turns. [page:0]"

try:
    from cerebras.cloud.sdk import Cerebras
except Exception as e:
    raise RuntimeError("Failed to import cerebras.cloud.sdk. Install/upgrade the Cerebras SDK package.") from e


def _coerce_bool_env(value: Optional[str]) -> Optional[bool]:
    if value is None:
        return None
    v = value.strip().lower()
    if v in {"1", "true", "t", "yes", "y", "on"}:
        return True
    if v in {"0", "false", "f", "no", "n", "off"}:
        return False
    return None


def _extract_chunk_text(chunk: Any) -> str:
    try:
        choices = getattr(chunk, "choices", None)
        if not choices:
            return ""
        choice0 = choices[0]
        delta = getattr(choice0, "delta", None)
        if delta is not None:
            content = getattr(delta, "content", None)
            if content is not None:
                return content
        message = getattr(choice0, "message", None)
        if message is not None:
            content = getattr(message, "content", None)
            if content is not None:
                return content
        return ""
    except Exception:
        return ""


def _max_output_limit_for_model(model: str) -> Optional[int]:
    if model == "zai-glm-4.7":
        return 40000
    return None


def _build_client(api_key: str) -> Cerebras:
    return Cerebras(api_key=api_key)


def _read_nonempty_line(prompt: str) -> Optional[str]:
    try:
        line = input(prompt)
    except EOFError:
        return None
    return line


def _print_stderr(text: str) -> None:
    sys.stderr.write(text + "\n")
    sys.stderr.flush()


def _validate_sampling(temperature: float, top_p: float) -> None:
    if temperature <= 0:
        raise ValueError("temperature must be > 0")
    if not (0 < top_p <= 1):
        raise ValueError("top_p must be in (0, 1]")


def _create_completion_stream(
    client: Cerebras,
    model: str,
    messages: List[Dict[str, str]],
    temperature: float,
    top_p: float,
    max_completion_tokens: int,
    clear_thinking: Optional[bool],
    disable_reasoning: Optional[bool],
) -> Any:
    kwargs: Dict[str, Any] = {
        "model": model,
        "messages": messages,
        "stream": True,
        "temperature": temperature,
        "top_p": top_p,
        "max_completion_tokens": max_completion_tokens,
    }
    if clear_thinking is not None:
        kwargs["clear_thinking"] = clear_thinking
    if disable_reasoning is not None:
        kwargs["disable_reasoning"] = disable_reasoning
    return client.chat.completions.create(**kwargs)


def run_chat(
    api_key: str,
    model: str,
    system_prompt: str,
    temperature: float,
    top_p: float,
    max_completion_tokens: int,
    clear_thinking: Optional[bool],
    disable_reasoning: Optional[bool],
) -> int:
    _validate_sampling(temperature, top_p)

    limit = _max_output_limit_for_model(model)
    if limit is not None and max_completion_tokens > limit:
        raise ValueError(f"max_completion_tokens too large for model {model}: {max_completion_tokens} > {limit}")

    client = _build_client(api_key)

    messages: List[Dict[str, str]] = []
    if system_prompt:
        messages.append({"role": "system", "content": system_prompt})

    _print_stderr("Commands: /exit  /quit  /reset  /system <text>  /params")

    while True:
        user_text = _read_nonempty_line("> ")
        if user_text is None:
            _print_stderr("")
            return 0

        user_text = user_text.strip()
        if not user_text:
            continue

        if user_text in {"/exit", "/quit"}:
            return 0

        if user_text == "/reset":
            messages = []
            if system_prompt:
                messages.append({"role": "system", "content": system_prompt})
            _print_stderr("Conversation reset.")
            continue

        if user_text.startswith("/system "):
            system_prompt = user_text[len("/system ") :].strip()
            messages = []
            if system_prompt:
                messages.append({"role": "system", "content": system_prompt})
            _print_stderr("System prompt updated and conversation reset.")
            continue

        if user_text == "/params":
            _print_stderr(
                f"model={model} temperature={temperature} top_p={top_p} max_completion_tokens={max_completion_tokens} "
                f"clear_thinking={clear_thinking} disable_reasoning={disable_reasoning}"
            )
            continue

        messages.append({"role": "user", "content": user_text})

        assistant_text_parts: List[str] = []
        try:
            stream = _create_completion_stream(
                client=client,
                model=model,
                messages=messages,
                temperature=temperature,
                top_p=top_p,
                max_completion_tokens=max_completion_tokens,
                clear_thinking=clear_thinking,
                disable_reasoning=disable_reasoning,
            )

            sys.stdout.write("assistant: ")
            sys.stdout.flush()

            for chunk in stream:
                piece = _extract_chunk_text(chunk)
                if piece:
                    assistant_text_parts.append(piece)
                    sys.stdout.write(piece)
                    sys.stdout.flush()

            sys.stdout.write("\n")
            sys.stdout.flush()

        except KeyboardInterrupt:
            _print_stderr("\nInterrupted.")
            return 130
        except Exception as e:
            _print_stderr(f"Request failed: {type(e).__name__}: {e}")
            try:
                messages.pop()
            except Exception:
                pass
            continue

        assistant_text = "".join(assistant_text_parts).strip()
        messages.append({"role": "assistant", "content": assistant_text})

    return 0


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--api-key", default=os.environ.get("CEREBRAS_API_KEY", ""), help="Cerebras API key")
    parser.add_argument("--model", default=os.environ.get("CEREBRAS_MODEL", "zai-glm-4.7"))
    parser.add_argument("--system", default=os.environ.get("CEREBRAS_SYSTEM_PROMPT", ""))
    parser.add_argument("--temperature", type=float, default=float(os.environ.get("CEREBRAS_TEMPERATURE", "1")))
    parser.add_argument("--top-p", type=float, default=float(os.environ.get("CEREBRAS_TOP_P", "0.95")))
    parser.add_argument("--max-completion-tokens", type=int, default=int(os.environ.get("CEREBRAS_MAX_COMPLETION_TOKENS", "40000")))

    env_clear_thinking = _coerce_bool_env(os.environ.get("CEREBRAS_CLEAR_THINKING"))
    env_disable_reasoning = _coerce_bool_env(os.environ.get("CEREBRAS_DISABLE_REASONING"))

    parser.add_argument(
        "--clear-thinking",
        choices=["true", "false", "unset"],
        default="unset",
        help="Set clear_thinking parameter (true/false) or unset to omit",
    )
    parser.add_argument(
        "--disable-reasoning",
        choices=["true", "false", "unset"],
        default="unset",
        help="Set disable_reasoning parameter (true/false) or unset to omit",
    )

    args = parser.parse_args()

    api_key = (args.api_key or "").strip()
    if not api_key:
        _print_stderr("Missing API key. Set CEREBRAS_API_KEY or pass --api-key.")
        return 2

    clear_thinking: Optional[bool]
    if args.clear_thinking == "unset":
        clear_thinking = env_clear_thinking
    else:
        clear_thinking = args.clear_thinking == "true"

    disable_reasoning: Optional[bool]
    if args.disable_reasoning == "unset":
        disable_reasoning = env_disable_reasoning
    else:
        disable_reasoning = args.disable_reasoning == "true"

    try:
        return run_chat(
            api_key=api_key,
            model=args.model,
            system_prompt=args.system,
            temperature=args.temperature,
            top_p=args.top_p,
            max_completion_tokens=args.max_completion_tokens,
            clear_thinking=clear_thinking,
            disable_reasoning=disable_reasoning,
        )
    except Exception as e:
        _print_stderr(f"Fatal error: {type(e).__name__}: {e}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
