import asyncio
import json
import os
import queue
import re
import threading
import time
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

from fastapi import FastAPI, HTTPException, Request, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse, StreamingResponse
from pydantic import BaseModel, Field, field_validator

from cerebras.cloud.sdk import Cerebras

__CEREBRAS_DOC_CITATIONS__ = "[page:1][page:0]"

SESSION_ID_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$")

DEFAULT_MODEL = os.environ.get("CEREBRAS_MODEL", "zai-glm-4.7")
DEFAULT_TEMPERATURE = float(os.environ.get("CEREBRAS_TEMPERATURE", "1"))
DEFAULT_TOP_P = float(os.environ.get("CEREBRAS_TOP_P", "0.95"))
DEFAULT_MAX_COMPLETION_TOKENS = int(os.environ.get("CEREBRAS_MAX_COMPLETION_TOKENS", "65000"))
MAX_HISTORY_MESSAGES = int(os.environ.get("CEREBRAS_MAX_HISTORY_MESSAGES", "50"))
SESSION_TTL_SECONDS = int(os.environ.get("CEREBRAS_SESSION_TTL_SECONDS", "86400"))
CORS_ALLOW_ORIGINS = [o.strip() for o in os.environ.get("CORS_ALLOW_ORIGINS", "*").split(",") if o.strip()]
CORS_ALLOW_CREDENTIALS = os.environ.get("CORS_ALLOW_CREDENTIALS", "true").strip().lower() in {"1", "true", "yes", "y"}
CORS_ALLOW_METHODS = [m.strip() for m in os.environ.get("CORS_ALLOW_METHODS", "*").split(",") if m.strip()]
CORS_ALLOW_HEADERS = [h.strip() for h in os.environ.get("CORS_ALLOW_HEADERS", "*").split(",") if h.strip()]

API_KEY = (os.environ.get("CEREBRAS_API_KEY") or "").strip()
if not API_KEY:
    raise RuntimeError("CEREBRAS_API_KEY is required")

_client = Cerebras(api_key=API_KEY)

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=CORS_ALLOW_ORIGINS,
    allow_credentials=CORS_ALLOW_CREDENTIALS,
    allow_methods=CORS_ALLOW_METHODS,
    allow_headers=CORS_ALLOW_HEADERS,
)


@dataclass
class SessionState:
    session_id: str
    messages: List[Dict[str, str]] = field(default_factory=list)
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)


_sessions: Dict[str, SessionState] = {}
_sessions_lock = asyncio.Lock()


def _now() -> float:
    return time.time()


def _extract_stream_text(chunk: Any) -> str:
    try:
        choices = getattr(chunk, "choices", None)
        if not choices:
            return ""
        c0 = choices[0]
        delta = getattr(c0, "delta", None)
        if delta is not None:
            content = getattr(delta, "content", None)
            if content is not None:
                return content
        message = getattr(c0, "message", None)
        if message is not None:
            content = getattr(message, "content", None)
            if content is not None:
                return content
        return ""
    except Exception:
        return ""


def _extract_message_content(resp: Any) -> str:
    try:
        choices = getattr(resp, "choices", None)
        if not choices:
            return ""
        msg = getattr(choices[0], "message", None)
        if msg is None:
            return ""
        content = getattr(msg, "content", None)
        return content or ""
    except Exception:
        return ""


def _extract_usage(resp: Any) -> Dict[str, Any]:
    try:
        usage = getattr(resp, "usage", None)
        if usage is None:
            return {}
        if isinstance(usage, dict):
            return usage
        out: Dict[str, Any] = {}
        for k in ("prompt_tokens", "completion_tokens", "total_tokens"):
            v = getattr(usage, k, None)
            if v is not None:
                out[k] = v
        details = getattr(usage, "prompt_tokens_details", None)
        if details is not None:
            out["prompt_tokens_details"] = details if isinstance(details, dict) else {}
        details2 = getattr(usage, "completion_tokens_details", None)
        if details2 is not None:
            out["completion_tokens_details"] = details2 if isinstance(details2, dict) else {}
        return out
    except Exception:
        return {}


def _sanitize_messages(messages: List[Dict[str, str]]) -> List[Dict[str, str]]:
    out: List[Dict[str, str]] = []
    for m in messages:
        role = (m.get("role") or "").strip()
        content = m.get("content")
        if role not in {"system", "user", "assistant", "tool"}:
            continue
        if content is None:
            continue
        if not isinstance(content, str):
            continue
        out.append({"role": role, "content": content})
    if MAX_HISTORY_MESSAGES > 0 and len(out) > MAX_HISTORY_MESSAGES:
        sys_idx = 0
        if out and out[0].get("role") == "system":
            sys_idx = 1
        keep = out[0:sys_idx] + out[max(sys_idx, len(out) - MAX_HISTORY_MESSAGES) :]
        return keep
    return out


async def _prune_expired_sessions() -> None:
    if SESSION_TTL_SECONDS <= 0:
        return
    cutoff = _now() - SESSION_TTL_SECONDS
    async with _sessions_lock:
        to_del = [sid for sid, st in _sessions.items() if st.updated_at < cutoff]
        for sid in to_del:
            _sessions.pop(sid, None)


async def _get_or_create_session(session_id: str, system_prompt: Optional[str]) -> SessionState:
    await _prune_expired_sessions()
    async with _sessions_lock:
        st = _sessions.get(session_id)
        if st is None:
            st = SessionState(session_id=session_id)
            if system_prompt is not None:
                sp = system_prompt.strip()
                if sp:
                    st.messages.append({"role": "system", "content": sp})
            _sessions[session_id] = st
            return st
        if system_prompt is not None and system_prompt.strip():
            if not st.messages or st.messages[0].get("role") != "system":
                st.messages.insert(0, {"role": "system", "content": system_prompt.strip()})
            else:
                st.messages[0] = {"role": "system", "content": system_prompt.strip()}
        return st


async def _update_session_messages(session_id: str, messages: List[Dict[str, str]]) -> None:
    async with _sessions_lock:
        st = _sessions.get(session_id)
        if st is None:
            st = SessionState(session_id=session_id)
            _sessions[session_id] = st
        st.messages = _sanitize_messages(messages)
        st.updated_at = _now()


async def _reset_session(session_id: str) -> None:
    async with _sessions_lock:
        _sessions.pop(session_id, None)


class ChatRequest(BaseModel):
    session_id: str = Field(..., min_length=1, max_length=128)
    message: str = Field(..., min_length=1, max_length=200000)
    system_prompt: Optional[str] = Field(None, max_length=200000)
    model: str = Field(default=DEFAULT_MODEL, min_length=1, max_length=200)
    temperature: float = Field(default=DEFAULT_TEMPERATURE, gt=0, le=2)
    top_p: float = Field(default=DEFAULT_TOP_P, gt=0, le=1)
    max_completion_tokens: int = Field(default=DEFAULT_MAX_COMPLETION_TOKENS, ge=1, le=200000)
    disable_reasoning: Optional[bool] = None

    @field_validator("session_id")
    @classmethod
    def validate_session_id(cls, v: str) -> str:
        v2 = v.strip()
        if not v2 or not SESSION_ID_RE.fullmatch(v2):
            raise ValueError("Invalid session_id")
        return v2

    @field_validator("message")
    @classmethod
    def validate_message(cls, v: str) -> str:
        v2 = v.strip()
        if not v2:
            raise ValueError("Empty message")
        return v2

    @field_validator("model")
    @classmethod
    def validate_model(cls, v: str) -> str:
        v2 = v.strip()
        if not v2:
            raise ValueError("Empty model")
        return v2


class ChatResponse(BaseModel):
    session_id: str
    content: str
    model: str
    usage: Dict[str, Any] = Field(default_factory=dict)


@app.get("/health")
async def health() -> JSONResponse:
    return JSONResponse({"status": "ok"})


@app.post("/sessions/{session_id}/reset")
async def reset_session(session_id: str) -> JSONResponse:
    sid = session_id.strip()
    if not sid or not SESSION_ID_RE.fullmatch(sid):
        raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_ENTITY, detail="Invalid session_id")
    await _reset_session(sid)
    return JSONResponse({"session_id": sid, "reset": True})


def _make_messages(existing: List[Dict[str, str]], user_text: str) -> List[Dict[str, str]]:
    msgs = list(existing)
    msgs.append({"role": "user", "content": user_text})
    return _sanitize_messages(msgs)


def _create_streaming_completion(
    model: str,
    messages: List[Dict[str, str]],
    temperature: float,
    top_p: float,
    max_completion_tokens: int,
    disable_reasoning: Optional[bool],
) -> Any:
    kwargs: Dict[str, Any] = {
        "model": model,
        "messages": messages,
        "stream": True,
        "temperature": temperature,
        "top_p": top_p,
        "max_completion_tokens": max_completion_tokens,
        "clear_thinking": False,
    }
    if disable_reasoning is not None:
        kwargs["disable_reasoning"] = disable_reasoning
    return _client.chat.completions.create(**kwargs)


def _create_nonstream_completion(
    model: str,
    messages: List[Dict[str, str]],
    temperature: float,
    top_p: float,
    max_completion_tokens: int,
    disable_reasoning: Optional[bool],
) -> Any:
    kwargs: Dict[str, Any] = {
        "model": model,
        "messages": messages,
        "stream": False,
        "temperature": temperature,
        "top_p": top_p,
        "max_completion_tokens": max_completion_tokens,
        "clear_thinking": False,
    }
    if disable_reasoning is not None:
        kwargs["disable_reasoning"] = disable_reasoning
    return _client.chat.completions.create(**kwargs)


@app.post("/chat", response_model=ChatResponse)
async def chat(req: ChatRequest) -> ChatResponse:
    st = await _get_or_create_session(req.session_id, req.system_prompt)
    messages = _make_messages(st.messages, req.message)

    try:
        resp = await asyncio.to_thread(
            _create_nonstream_completion,
            req.model,
            messages,
            req.temperature,
            req.top_p,
            req.max_completion_tokens,
            req.disable_reasoning,
        )
    except Exception as e:
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=str(e)) from e

    content = _extract_message_content(resp)
    messages.append({"role": "assistant", "content": content})
    await _update_session_messages(req.session_id, messages)

    return ChatResponse(
        session_id=req.session_id,
        content=content,
        model=req.model,
        usage=_extract_usage(resp),
    )


@app.post("/chat/stream")
async def chat_stream(req: ChatRequest, request: Request) -> StreamingResponse:
    st = await _get_or_create_session(req.session_id, req.system_prompt)
    messages = _make_messages(st.messages, req.message)

    q: "queue.Queue[Any]" = queue.Queue()
    sentinel = object()
    stop_event = threading.Event()

    def worker() -> None:
        try:
            stream = _create_streaming_completion(
                model=req.model,
                messages=messages,
                temperature=req.temperature,
                top_p=req.top_p,
                max_completion_tokens=req.max_completion_tokens,
                disable_reasoning=req.disable_reasoning,
            )
            for chunk in stream:
                if stop_event.is_set():
                    break
                piece = _extract_stream_text(chunk)
                if piece:
                    q.put(piece)
            q.put(sentinel)
        except Exception as e:
            q.put(e)
            q.put(sentinel)

    threading.Thread(target=worker, daemon=True).start()

    async def event_generator() -> Any:
        assistant_parts: List[str] = []
        try:
            yield b"event: meta\ndata: " + json.dumps({"session_id": req.session_id, "model": req.model}).encode("utf-8") + b"\n\n"
            while True:
                if await request.is_disconnected():
                    stop_event.set()
                    break
                item = await asyncio.to_thread(q.get)
                if item is sentinel:
                    break
                if isinstance(item, Exception):
                    raise item
                if not isinstance(item, str) or not item:
                    continue
                assistant_parts.append(item)
                payload = json.dumps({"delta": item}, ensure_ascii=False).encode("utf-8")
                yield b"data: " + payload + b"\n\n"
            full = "".join(assistant_parts)
            messages2 = list(messages)
            messages2.append({"role": "assistant", "content": full})
            await _update_session_messages(req.session_id, messages2)
            yield b"event: done\ndata: " + json.dumps({"content": full}, ensure_ascii=False).encode("utf-8") + b"\n\n"
        except Exception as e:
            stop_event.set()
            err = json.dumps({"error": str(e)}, ensure_ascii=False).encode("utf-8")
            yield b"event: error\ndata: " + err + b"\n\n"

    return StreamingResponse(event_generator(), media_type="text/event-stream")
